graphql.query:
query getOrderDetails($id: ID!, $exposeNotAppliedDiscounts: Boolean, $exposeRootQuoteItems: Boolean) {
  getQuote(
    id: $id
    exposeNotAppliedDiscounts: $exposeNotAppliedDiscounts
    exposeRootQuoteItems: $exposeRootQuoteItems
  ) {
    ...QuoteOrderDetailsFragment
    __typename
  }
}

